from collections import OrderedDict
from threading import Lock
from typing import TypeVar, Generic, Optional, Callable
import time

K = TypeVar('K')
V = TypeVar('V')

class LRUCache(Generic[K, V]):
    """EGRR_PATTERN: Thread-safe LRU Cache implementation."""

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("Capacity must be positive")
        self.capacity = capacity
        self.cache: OrderedDict[K, V] = OrderedDict()
        self.lock = Lock()

    def get(self, key: K) -> Optional[V]:
        """Get item and mark as recently used."""
        with self.lock:
            if key not in self.cache:
                return None
            # Move to end (most recently used)
            self.cache.move_to_end(key)
            return self.cache[key]

    def put(self, key: K, value: V) -> None:
        """Put item, evicting LRU if at capacity."""
        with self.lock:
            if key in self.cache:
                self.cache.move_to_end(key)
            else:
                if len(self.cache) >= self.capacity:
                    self.cache.popitem(last=False)
            self.cache[key] = value

    def __contains__(self, key: K) -> bool:
        with self.lock:
            return key in self.cache

    def __len__(self) -> int:
        return len(self.cache)

class TTLCache(Generic[K, V]):
    """EGRR_PATTERN: Cache with time-to-live expiration."""

    def __init__(self, ttl_seconds: float = 300.0, max_size: int = 1000):
        if ttl_seconds <= 0:
            raise ValueError("TTL must be positive")
        self.ttl = ttl_seconds
        self.max_size = max_size
        self.cache: dict[K, tuple[V, float]] = {}
        self.lock = Lock()

    def get(self, key: K) -> Optional[V]:
        with self.lock:
            if key not in self.cache:
                return None
            value, timestamp = self.cache[key]
            if time.time() - timestamp > self.ttl:
                del self.cache[key]
                return None
            return value

    def put(self, key: K, value: V) -> None:
        with self.lock:
            # Evict expired entries if at max size
            if len(self.cache) >= self.max_size:
                self._cleanup()
            self.cache[key] = (value, time.time())

    def _cleanup(self) -> None:
        """Remove expired entries."""
        now = time.time()
        expired = [k for k, (_, ts) in self.cache.items() if now - ts > self.ttl]
        for k in expired:
            del self.cache[k]

def memoize(func: Callable) -> Callable:
    """EGRR_PATTERN: Simple memoization decorator."""
    cache = {}

    def wrapper(*args, **kwargs):
        key = (args, tuple(sorted(kwargs.items())))
        if key not in cache:
            cache[key] = func(*args, **kwargs)
        return cache[key]

    wrapper.cache_clear = lambda: cache.clear()
    return wrapper
